<template>
  <main class="eng-page"><span class="eng-eyebrow">SOFEP / CHĂM SÓC KHÁCH HÀNG</span><h1>Góp ý riêng</h1><p class="eng-muted">Chỉ Admin được xem nội dung, thông tin liên hệ và ảnh đính kèm.</p>
    <div v-if="error" class="eng-error" role="alert">{{ error }}</div><div v-if="message" class="eng-success" role="status">{{ message }}</div>
    <form class="eng-panel" @submit.prevent="page=1;load()"><div class="eng-grid"><div><label for="feedback-search">Tìm nội dung/email</label><input id="feedback-search" v-model="q" maxlength="160"></div><div><label for="feedback-filter-topic">Chủ đề</label><select id="feedback-filter-topic" v-model="topic"><option value="">Tất cả</option><option v-for="(label,key) in topics" :value="key" :key="key">{{ label }}</option></select></div></div><label for="feedback-status">Trạng thái</label><select id="feedback-status" v-model="status"><option value="">Tất cả</option><option v-for="(label,key) in statuses" :value="key" :key="key">{{ label }}</option></select><div class="eng-actions"><button class="eng-btn" :disabled="loading">{{ loading?'Đang tải…':'Tìm / Lọc' }}</button></div></form>
    <div class="eng-grid"><section class="eng-panel"><h2>Danh sách góp ý</h2><p v-if="loading" role="status">Đang tải…</p><div v-else class="eng-list"><button v-for="row in rows" :key="row.id" class="eng-item text-start" @click="show(row.id)"><strong>#{{ row.id }} · {{ topics[row.topic] }}</strong><p class="eng-muted">{{ date(row.created_at) }} · {{ statuses[row.status] }}</p></button><p v-if="!rows.length" class="eng-muted">Chưa có góp ý phù hợp.</p></div><div class="eng-actions"><button class="eng-btn secondary" :disabled="page<=1" @click="page--;load()">Trước</button><span>{{ page }}/{{ lastPage }}</span><button class="eng-btn secondary" :disabled="page>=lastPage" @click="page++;load()">Sau</button></div></section>
      <section class="eng-panel"><p v-if="detailLoading" role="status">Đang mở góp ý…</p><template v-else-if="detail"><h2>Góp ý #{{ detail.id }}</h2><span class="eng-tag">{{ topics[detail.topic] }}</span><p class="eng-body" style="white-space:pre-wrap;overflow-wrap:anywhere">{{ detail.body }}</p><p class="eng-muted">Email: {{ detail.email || 'Không cung cấp' }}<br>Điện thoại: {{ detail.phone || 'Không cung cấp' }}<br>Tài khoản Customer: {{ detail.customer_id || 'Khách vãng lai' }}</p><div class="eng-images"><a v-for="image in images" :key="image.id" :href="image.url" target="_blank" rel="noopener"><img :src="image.url" alt="Ảnh góp ý riêng"></a></div>
      <label for="feedback-edit-status">Trạng thái xử lý</label><select id="feedback-edit-status" v-model="detail.status"><option v-for="(label,key) in statuses" :value="key" :key="key">{{ label }}</option></select><label for="feedback-note">Ghi chú nội bộ</label><textarea id="feedback-note" v-model="detail.internal_note" maxlength="5000"></textarea><div class="eng-actions"><button class="eng-btn" :disabled="busy" @click="update">Lưu xử lý</button></div>
      <div class="eng-divider"><h3>Phản hồi riêng</h3><p v-if="detail.reply" class="eng-muted">Đã phản hồi: {{ detail.reply }}</p><label for="reply-channel">Kênh gửi</label><select id="reply-channel" v-model="channel"><option v-if="detail.customer_id" value="in_app">Hộp thư Customer</option><option v-if="emailEnabled && detail.email" value="email">Email đã được bật và phê duyệt</option></select><p v-if="!detail.customer_id && !emailEnabled" class="eng-muted">Khách vãng lai chưa có hộp thư. Email tự động chưa được bật; dùng ghi chú để lưu phương án xử lý và liên hệ qua kênh đã xác minh.</p><label for="feedback-reply">Nội dung phản hồi</label><textarea id="feedback-reply" v-model="reply" maxlength="5000"></textarea><div class="eng-actions"><button class="eng-btn secondary" :disabled="busy || !reply.trim() || (!detail.customer_id && !emailEnabled)" @click="confirmReply=true">Xem trước phản hồi</button></div><div v-if="confirmReply" class="eng-panel"><p style="white-space:pre-wrap">{{ reply }}</p><p class="eng-muted">Xác nhận gửi riêng qua {{ channel==='email'?'email':'hộp thư Customer' }}?</p><div class="eng-actions"><button class="eng-btn" :disabled="busy" @click="sendReply">Xác nhận gửi</button><button class="eng-btn secondary" @click="confirmReply=false">Quay lại</button></div></div></div>
      </template><p v-else class="eng-muted">Chọn một góp ý để xem chi tiết.</p></section>
    </div>
  </main>
</template>
<script>
import { engagementApi, engagementError, engagementDate, topicLabels } from '../../services/engagement';
export default {
  data:()=>({topics:topicLabels,statuses:{unread:'Chưa đọc',processing:'Đang xử lý',resolved:'Đã xử lý'},q:'',topic:'',status:'',rows:[],page:1,lastPage:1,loading:false,busy:false,error:'',message:'',detail:null,detailLoading:false,images:[],reply:'',channel:'in_app',confirmReply:false,emailEnabled:false,requestId:0}),
  mounted(){this.load();},beforeUnmount(){this.requestId++;this.clearImages();},
  methods:{date:engagementDate,clearImages(){this.images.forEach(i=>URL.revokeObjectURL(i.url));this.images=[];},
    async load(){this.loading=true;this.error='';try{const {data}=await engagementApi('admin/gop-y?'+new URLSearchParams({q:this.q,topic:this.topic,status:this.status,page:this.page}));this.rows=data.data.data;this.lastPage=data.data.last_page;}catch(e){this.error=engagementError(e);}finally{this.loading=false;}},
    async show(id){const request=++this.requestId;this.detailLoading=true;this.error='';this.confirmReply=false;this.clearImages();try{const {data}=await engagementApi('admin/gop-y/'+id);if(request!==this.requestId)return;this.detail=data.data;this.emailEnabled=data.email_reply_enabled;this.channel=this.detail.customer_id?'in_app':'email';this.reply='';for(const image of data.images){const response=await engagementApi('admin/gop-y/'+id+'/anh/'+image.id,{responseType:'blob'});if(request!==this.requestId)return;this.images.push({id:image.id,url:URL.createObjectURL(response.data)});}}catch(e){if(request===this.requestId)this.error=engagementError(e);}finally{if(request===this.requestId)this.detailLoading=false;}},
    async update(){if(this.busy)return;this.busy=true;this.error='';try{await engagementApi('admin/gop-y/'+this.detail.id,{method:'patch',data:{status:this.detail.status,internal_note:this.detail.internal_note}});this.message='Đã lưu trạng thái và ghi chú nội bộ.';await this.load();}catch(e){this.error=engagementError(e);}finally{this.busy=false;}},
    async sendReply(){if(this.busy)return;this.busy=true;this.error='';try{const {data}=await engagementApi('admin/gop-y/'+this.detail.id+'/phan-hoi',{method:'post',data:{body:this.reply,channel:this.channel}});this.message=data.message;this.confirmReply=false;await this.show(this.detail.id);}catch(e){this.error=engagementError(e);}finally{this.busy=false;}}
  }
};
</script>
<style src="../../assets/css/engagement.css"></style>
